            work.TextVersionUp[monsno - 1] &= ~bit;
    }
	public static int GetZukanNo(global::Pml.PokePara.PokemonParam pokemonParam) {
        bool isZenkoku = GetZenkokuFlag();
        var catalog = GameData.DataManager.GetPokemonCatalog(GameData.DataManager.GetUniqueID(pokemonParam));
        if (isZenkoku)
            return (int)pokemonParam.GetMonsNo();

        return catalog.SinnohNo;
    }
	static ZukanWork() { }
}
